/**
 * Browser (UX) Canary.
 *
 * A CloudWatch Synthetics Puppeteer canary that complements the API health
 * canary by exercising the real browser experience across a configurable
 * user journey (a home page plus any number of additional pages). For each
 * page it:
 *
 *   1. Loads the page in a headless browser (following redirects naturally).
 *   2. Watches network responses and uncaught page errors during the visit
 *      (generic, app-agnostic failure signals — catches backend calls that
 *      fail with a 4xx/5xx even if the page itself still returns 200).
 *   3. Asserts that the page's real content rendered (a positive, per-page
 *      selector — e.g. at least one list item) rather than only checking
 *      that some structural/chrome element (header, body) is present. This
 *      is the primary signal: some app failures are rendered server-side as
 *      a normal 200 page with an error message in place of the real
 *      content, which no HTTP-status or top-level navigation check can ever
 *      detect — only "did the expected content actually appear" can.
 *      Some pages have a legitimate, non-error empty state (e.g. a list page
 *      that correctly shows "No data available" when there is nothing to
 *      show yet). For those pages, a configured `emptyStateSelector` marks
 *      that state as OK instead of failing the canary on missing content —
 *      a data-dependent page must not report an outage just because no data
 *      exists yet.
 *   4. As a secondary, non-authoritative signal, flags (and fails on) the
 *      presence of a *visible* generic error indicator (Bootstrap's
 *      `.alert-danger` convention by default, configurable). Visibility
 *      matters: some templates render a hidden, empty error placeholder on
 *      every page load (populated by client-side JS only when a real error
 *      occurs), so mere DOM presence is not a reliable signal — a hidden,
 *      empty error banner is not an error to a real user and must not be to
 *      the canary either. This remains corroborating evidence only — the
 *      canary does not depend on any specific error text, since error copy
 *      is application-defined and can change.
 *
 * A failure on any page drives an availability alarm, so UX/page-load/
 * content problems enter the same routing → DevOps Agent triage flow. The
 * specific failing page, URL, and reason are logged so the investigation has
 * concrete evidence to work from.
 *
 * Configuration (environment variables set by the construct):
 *   L1T_UX_URL_PARAMETER_NAME   SSM parameter holding the base site URL
 *   L1T_UX_URL                  inline base site URL (takes precedence)
 *   L1T_UX_KEY_SELECTOR         CSS selector of a key element on the home page (default: body)
 *   L1T_UX_MAX_LOAD_MS          soft page-load budget in ms (logged; default 10000)
 *   L1T_UX_USER_ID              optional query param appended to journey page URLs
 *   L1T_UX_ERROR_SELECTOR       secondary generic error-indicator selector (default: .alert-danger)
 *   L1T_UX_JOURNEY_PAGES        JSON array of journey page definitions (see below); inline value
 *   L1T_UX_JOURNEY_PAGES_PARAMETER_NAME  SSM parameter holding the same JSON, if not inline
 *
 * Journey page definition shape (each entry of the JSON array):
 *   {
 *     "name": "adoption-list",             // step name, used for logging/executeStep label
 *     "path": "/some/path",                // appended to the base URL
 *     "contentSelector": ".pet-item",       // positive selector that must be present when healthy
 *     "emptyStateSelector": ".alert-warning", // optional: a valid non-error empty state
 *     "extraQuery": "petType=puppy",        // optional: extra query string appended to the URL
 *     "steps": [ ... ]                      // optional: interaction sequence, see below
 *   }
 *
 * If no journey pages are configured, the canary checks only the home page.
 *
 * Interaction steps (Slice — write-path/transactional checks):
 *
 * The checks above (positive content selector, network/JS errors) verify
 * that a page *renders* correctly — the read path. Many real outages live on
 * the write/transactional path instead: the page loads fine, but "Add to
 * Cart" silently does nothing, or a form submit 500s. A page that only ever
 * navigates and asserts can never observe that, because nothing is ever
 * clicked or submitted.
 *
 * `steps` lets a journey page describe an ordered sequence of interactions
 * to perform after navigating to `path`, before the (optional) final content
 * assertion. Each step is one of:
 *
 *   { "action": "click", "selector": ".add-to-cart-btn", "timeout": 10000 }
 *   { "action": "type", "selector": "#search", "value": "puppy", "delay": 20, "timeout": 10000 }
 *   { "action": "waitForSelector", "selector": ".cart-badge", "timeout": 10000 }
 *   { "action": "assertVisible", "selector": ".cart-badge" }
 *
 * Steps execute in order; the first step that fails (element not found,
 * click target not clickable, assertion not visible) fails the whole page
 * check with a message identifying the step index and action, so the
 * investigation has a precise failure point rather than just "page broke
 * somewhere." The network/JS-error listeners span the entire page visit
 * (navigation AND step execution), so a click-triggered backend call that
 * fails with a 4xx/5xx is caught by the exact same generic mechanism that
 * already catches load-time failures — no extra wiring needed.
 *
 * `steps` and `contentSelector` can be combined (steps run first, e.g. to
 * reach a piece of UI that only appears after an interaction, followed by
 * the usual content assertion) or `steps` can be used alone, typically
 * ending in its own `assertVisible`/`waitForSelector` step as the final
 * success signal.
 *
 * Not supported: authentication/session flows (login forms, MFA, cookie
 * persistence across separate canary runs). See the project README for why
 * this is an intentional scope boundary, not an oversight.
 */

'use strict';

// The Synthetics runtime provides these modules only inside a canary. Load
// them lazily/tolerantly so the pure decision logic (evaluatePageResult) can
// be unit-tested outside the runtime.
let synthetics;
let log;
try {
    // eslint-disable-next-line global-require
    synthetics = require('Synthetics');
    // eslint-disable-next-line global-require
    log = require('SyntheticsLogger');
} catch (e) {
    synthetics = {
        executeStep: async (_name, fn) => fn(),
        getPage: async () => {
            throw new Error('Synthetics runtime not available (getPage requires the canary runtime)');
        },
        takeScreenshot: async () => {},
    };
    log = { info: () => {}, error: () => {} };
}

/**
 * Resolve the journey pages to visit (beyond the home page) from
 * configuration. Each entry defines a positive content selector that must be
 * present for the page to be considered healthy — this is app-specific per
 * page, but the mechanism (assert real content rendered) is the generic,
 * reusable part.
 *
 * @returns {Promise<Array<{name:string,path:string,contentSelector:string,emptyStateSelector:(string|undefined),extraQuery:(string|undefined)}>>}
 */
async function resolveJourneyPages() {
    const inline = process.env.L1T_UX_JOURNEY_PAGES;
    if (inline && inline.trim().length > 0) {
        return JSON.parse(inline);
    }
    const paramName = process.env.L1T_UX_JOURNEY_PAGES_PARAMETER_NAME;
    if (paramName) {
        const { SSMClient, GetParameterCommand } = require('@aws-sdk/client-ssm');
        const ssm = new SSMClient({});
        const res = await ssm.send(new GetParameterCommand({ Name: paramName, WithDecryption: false }));
        if (!res.Parameter || !res.Parameter.Value) {
            throw new Error(`SSM parameter ${paramName} has no value`);
        }
        return JSON.parse(res.Parameter.Value);
    }
    return [];
}

async function resolveUrl() {
    const inline = process.env.L1T_UX_URL;
    if (inline && inline.trim().length > 0) {
        return inline.trim();
    }
    const paramName = process.env.L1T_UX_URL_PARAMETER_NAME;
    if (!paramName) {
        throw new Error('No UX target URL configured (set L1T_UX_URL or L1T_UX_URL_PARAMETER_NAME)');
    }
    const { SSMClient, GetParameterCommand } = require('@aws-sdk/client-ssm');
    const ssm = new SSMClient({});
    const res = await ssm.send(new GetParameterCommand({ Name: paramName, WithDecryption: false }));
    if (!res.Parameter || !res.Parameter.Value) {
        throw new Error(`SSM parameter ${paramName} has no value`);
    }
    return res.Parameter.Value;
}

/**
 * Attach generic, app-agnostic failure listeners to a page: any network
 * response with status >= 400, and any uncaught page-level JS exception.
 * Returns an object the caller can inspect after navigation/settle.
 *
 * @param {import('puppeteer').Page} page
 * @returns {{ failedResponses: Array<{url:string,status:number}>, pageErrors: string[] }}
 */
function attachFailureListeners(page) {
    const failedResponses = [];
    const pageErrors = [];

    const onResponse = (response) => {
        const status = response.status();
        if (status >= 400) {
            failedResponses.push({ url: response.url(), status });
        }
    };
    const onPageError = (err) => {
        pageErrors.push(String(err && err.message ? err.message : err));
    };

    page.on('response', onResponse);
    page.on('pageerror', onPageError);

    return {
        failedResponses,
        pageErrors,
        detach: () => {
            page.off('response', onResponse);
            page.off('pageerror', onPageError);
        },
    };
}

/**
 * Pure decision logic: given the observed signals for a page visit, decide
 * whether the page is healthy and, if not, why. Kept separate from the
 * Puppeteer I/O above so it is directly unit-testable.
 *
 * Evaluation order (first failing check wins, for a clear error message):
 *   1. Expected content missing — UNLESS the page's configured valid empty
 *      state (e.g. "No data available") is present, in which case missing
 *      content is not a failure.
 *   2. Visible generic error indicator present (secondary signal). A
 *      present-but-hidden/empty error element (a dormant template
 *      placeholder) does not count.
 *   3. Any network response >= 400 observed during the visit.
 *   4. Any uncaught page-level JS error observed during the visit.
 *
 * @param {{name:string,url:string,contentSelector:string,errorSelector:string,emptyStateSelector:(string|undefined)}} page
 * @param {{contentPresent:boolean,emptyStatePresent:boolean,dangerVisible:boolean,failedResponses:Array<{url:string,status:number}>,pageErrors:string[]}} signals
 * @returns {{ok:boolean,reason:(string|null)}}
 */
function evaluatePageResult(page, signals) {
    if (!signals.contentPresent && !signals.emptyStatePresent) {
        return { ok: false, reason: `Page "${page.name}" (${page.url}) did not render its expected content (${page.contentSelector})` };
    }
    if (signals.dangerVisible) {
        return { ok: false, reason: `Page "${page.name}" (${page.url}) shows a generic error indicator (${page.errorSelector})` };
    }
    if (signals.failedResponses.length > 0) {
        const worst = signals.failedResponses[0];
        return { ok: false, reason: `Page "${page.name}" (${page.url}) had a failed network response: ${worst.status} ${worst.url}` };
    }
    if (signals.pageErrors.length > 0) {
        return { ok: false, reason: `Page "${page.name}" (${page.url}) had an uncaught error: ${signals.pageErrors[0]}` };
    }
    return { ok: true, reason: null };
}

/**
 * Check whether an element matching `selector` exists in the DOM AND is
 * actually visible (not `display: none`, not zero-size, not detached).
 * Puppeteer's `page.$()` only checks DOM presence, which is not sufficient
 * for elements like a dormant, hidden error placeholder that some apps
 * always render and populate via client-side JS only when a real error
 * occurs.
 *
 * @param {import('puppeteer').Page} page
 * @param {string} selector
 * @returns {Promise<boolean>} true if at least one matching element is visible
 */
async function isSelectorVisible(page, selector) {
    try {
        return await page.evaluate((sel) => {
            const elements = document.querySelectorAll(sel);
            for (const el of elements) {
                const style = window.getComputedStyle(el);
                if (style.display === 'none' || style.visibility === 'hidden' || Number(style.opacity) === 0) {
                    continue;
                }
                const rect = el.getBoundingClientRect();
                if (rect.width > 0 && rect.height > 0) {
                    return true;
                }
            }
            return false;
        }, selector);
    } catch (e) {
        return false;
    }
}

/** Default per-step timeout in milliseconds, when a step does not specify its own. */
const DEFAULT_STEP_TIMEOUT_MS = 10000;

/**
 * Execute a single interaction step against the page. Throws a descriptive
 * error (including the step index and action, for precise triage) if the
 * step fails.
 *
 * Supported actions:
 *   click            — page.click(selector)
 *   type             — page.type(selector, value, { delay })
 *   waitForSelector  — page.waitForSelector(selector) without asserting visibility beyond DOM presence
 *   assertVisible    — asserts the selector is present AND visible (via isSelectorVisible)
 *
 * @param {import('puppeteer').Page} page
 * @param {{action:string,selector:(string|undefined),value:(string|undefined),delay:(number|undefined),timeout:(number|undefined)}} step
 * @param {number} index step's position in the sequence, for error messages
 */
async function runStep(page, step, index) {
    const timeout = step.timeout ?? DEFAULT_STEP_TIMEOUT_MS;
    const label = `step[${index}] ${step.action}${step.selector ? ` (${step.selector})` : ''}`;

    switch (step.action) {
        case 'click':
            try {
                await page.waitForSelector(step.selector, { timeout, visible: true });
                await page.click(step.selector);
            } catch (e) {
                throw new Error(`${label} failed: ${e.message}`);
            }
            return;

        case 'type':
            try {
                await page.waitForSelector(step.selector, { timeout, visible: true });
                await page.type(step.selector, step.value ?? '', { delay: step.delay ?? 0 });
            } catch (e) {
                throw new Error(`${label} failed: ${e.message}`);
            }
            return;

        case 'waitForSelector':
            try {
                await page.waitForSelector(step.selector, { timeout });
            } catch (e) {
                throw new Error(`${label} failed: selector did not appear within ${timeout}ms`);
            }
            return;

        case 'assertVisible': {
            const deadline = Date.now() + timeout;
            let visible = false;
            do {
                visible = await isSelectorVisible(page, step.selector);
                if (visible) {
                    break;
                }
                await new Promise((r) => setTimeout(r, 200));
            } while (Date.now() < deadline);
            if (!visible) {
                throw new Error(`${label} failed: selector was not visible within ${timeout}ms`);
            }
            return;
        }

        default:
            throw new Error(`${label} failed: unknown step action "${step.action}"`);
    }
}

/**
 * Execute an ordered sequence of interaction steps against the page, in
 * order, stopping at (and throwing from) the first failing step.
 *
 * @param {import('puppeteer').Page} page
 * @param {Array<object>} steps
 */
async function runSteps(page, steps) {
    for (let i = 0; i < steps.length; i++) {
        await runStep(page, steps[i], i);
    }
}

/**
 * Visit a single page, apply the generic network/JS-error checks plus the
 * page's positive content assertion and the secondary generic error-selector
 * check, and throw a descriptive error if the page is unhealthy.
 *
 * @param {import('puppeteer').Page} page
 * @param {string} name step/page name, used for logging and the executeStep label
 * @param {string} url full URL to visit
 * @param {string} contentSelector CSS selector that must be present when the page is healthy
 * @param {string} errorSelector secondary generic error-indicator selector
 * @param {number} maxLoadMs soft page-load budget in ms (logged only)
 * @param {(string|undefined)} emptyStateSelector optional selector marking a valid, non-error empty state
 * @param {(Array<object>|undefined)} steps optional interaction sequence run after navigation, before the content assertion
 */
async function checkPage(page, name, url, contentSelector, errorSelector, maxLoadMs, emptyStateSelector, steps) {
    const listeners = attachFailureListeners(page);
    const startedAt = Date.now();
    try {
        const response = await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 30000 });
        const status = response ? response.status() : null;

        // Let any async fetches/XHRs triggered on load settle briefly so the
        // response listener has a chance to observe them.
        await new Promise((r) => setTimeout(r, 1500));

        // Run any configured interaction sequence (click/type/wait/assert)
        // before the content assertion below. A failing step throws
        // immediately with a precise step-index/action message, so a
        // write-path failure (e.g. "Add to Cart" not working) is reported
        // distinctly from a read-path rendering failure.
        if (steps && steps.length > 0) {
            await runSteps(page, steps);
        }

        const loadMs = Date.now() - startedAt;

        // Primary signal: does the page's real content exist? Skipped when
        // no contentSelector is configured (a steps-only page is expected to
        // have already asserted its own success via an assertVisible or
        // waitForSelector step above).
        let contentPresent = true;
        if (contentSelector) {
            contentPresent = false;
            try {
                await page.waitForSelector(contentSelector, { timeout: 10000 });
                contentPresent = true;
            } catch (e) {
                contentPresent = false;
            }
        }

        // If content is missing, check whether this page has a configured
        // valid empty state (e.g. "No data available") — a data-dependent
        // page must not report an outage just because no data exists yet.
        let emptyStatePresent = false;
        if (!contentPresent && emptyStateSelector) {
            try {
                emptyStatePresent = (await page.$(emptyStateSelector)) !== null;
            } catch (e) {
                emptyStatePresent = false;
            }
        }

        // Secondary, non-authoritative signal: a *visible* generic error
        // indicator. DOM presence alone is not enough — some templates
        // always render a hidden, empty error placeholder that client-side
        // JS only populates/shows on a real error.
        const dangerVisible = await isSelectorVisible(page, errorSelector);

        const result = evaluatePageResult(
            { name, url, contentSelector, errorSelector },
            { contentPresent, emptyStatePresent, dangerVisible, failedResponses: listeners.failedResponses, pageErrors: listeners.pageErrors },
        );

        log.info(
            JSON.stringify({
                l1tUxCheck: true,
                page: name,
                url,
                finalUrl: page.url(),
                status,
                loadMs,
                withinBudget: loadMs <= maxLoadMs,
                contentPresent,
                emptyStatePresent,
                dangerVisible,
                failedResponses: listeners.failedResponses,
                pageErrors: listeners.pageErrors,
                ok: result.ok,
                timestamp: new Date().toISOString(),
            }),
        );

        if (!result.ok) {
            throw new Error(result.reason);
        }
    } finally {
        listeners.detach();
    }
}

const pageLoadBlueprint = async function () {
    const baseUrl = (await resolveUrl()).replace(/\/$/, '');
    const keySelector = process.env.L1T_UX_KEY_SELECTOR || 'body';
    const errorSelector = process.env.L1T_UX_ERROR_SELECTOR || '.alert-danger';
    const maxLoadMs = Number(process.env.L1T_UX_MAX_LOAD_MS) || 10000;
    const userId = process.env.L1T_UX_USER_ID;
    const journeyPages = await resolveJourneyPages();

    const page = await synthetics.getPage();

    const homeQuery = userId ? `?userId=${userId}` : '';
    await synthetics.executeStep('home', async function () {
        await checkPage(page, 'home', `${baseUrl}/${homeQuery}`, keySelector, errorSelector, maxLoadMs);
    });
    await synthetics.takeScreenshot('home', 'loaded');

    for (const journeyPage of journeyPages) {
        const queryParts = [];
        if (userId) {
            queryParts.push(`userId=${userId}`);
        }
        if (journeyPage.extraQuery) {
            queryParts.push(journeyPage.extraQuery);
        }
        const query = queryParts.length > 0 ? `?${queryParts.join('&')}` : '';
        const url = `${baseUrl}${journeyPage.path}${query}`;
        await synthetics.executeStep(journeyPage.name, async function () {
            await checkPage(
                page,
                journeyPage.name,
                url,
                journeyPage.contentSelector,
                errorSelector,
                maxLoadMs,
                journeyPage.emptyStateSelector,
                journeyPage.steps,
            );
        });
        await synthetics.takeScreenshot(journeyPage.name, 'loaded');
    }
};

exports.handler = async () => {
    return await pageLoadBlueprint();
};

// Exported for unit testing (ignored by the Synthetics runtime).
exports.__test__ = {
    evaluatePageResult,
    attachFailureListeners,
    isSelectorVisible,
    resolveJourneyPages,
    runStep,
    runSteps,
};
